spec.particles:
**No ember-style records.** The particles are 0-3 satellite beads living inside the field, carried in the uniform as float4 (x, y, r, 0). They sit in the uniform because a smooth union needs them in the same SDF as the tube and head. Each is a closed-form function of the ignition seed (fire::Hash chain) and age, computed in Rust (design item 4):
- born at the pinch time t_p;
- u(age) = u0 + (1-u0)(1 - e^(-(age - t_p)/tau_j));
- radius grows in over 20 ms and is absorbed (radius to 0) as u goes from 0.85 to 0.99;
- perpendicular jitter decays with a 60 ms constant.

Positions are expressed in u along B to H. B is continuous and H follows the cursor, so a retarget moves a bead's target the way it moves the head drop. The bead radii and their clock are continuous across a retarget: in the prototype, 5.12/3.04/2.57 → 5.10/3.03/2.56 over 2 ms.

An optional spray of flung droplets as records (a new drop-disc kind with a rim) is left as an owner question. It is off in this spec; Liquid Glass is calm.

spec.msl_sketch:
// In shaders.metal. Kind::Liquid gets KIND_LIQUID 6u, pinned by metallib.rs's kind test like KIND_FIRE.
struct LiquidU {
    float2 c[4]; float4 hole; float2 origin; float2 tail; float2 dir;   // shared prefix (FireU's)
    float len; float unit; float age; float life; uint seed; float reach; // reach in px
    float2 b; float2 h;                 // spine B, head H
    float radius; float neck;           // R_eff, n
    float inv_len2; float lip;          // 1/|H-B|^2 (0: no tube), 4 n R / |H-B|
    float2 half_box; float round;       // head drop
    float k;                            // smooth-union width, px
    float4 bead[3];                     // xy, r (<= 0 none), unused
    float2 light; float envelope; float inv_bezel;
    float body; float rim; float spec; float back;
    float pad0; float pad1; float pad2; float pad3;
};  // 60 floats, 240 bytes: hole at byte 32, bead[0] at byte 144

static inline float3 liquid_smin(float3 a, float3 b, float k) {   // iq quadratic, normalised k; exact gradient
    float h = 1.0 - min(abs(a.x - b.x) / (4.0 * k), 1.0);
    float s = h * h * k; float w = 0.5 * h;
    return a.x < b.x ? float3(a.x - s, mix(a.yz, b.yz, w)) : float3(b.x - s, mix(b.yz, a.yz, w));
}
static inline float2 liquid_dir(float2 v, float l) { return l > 1e-3 ? v / l : float2(0.0); }

static inline float3 liquid_field(float2 p, constant LiquidU& L) {
    float2 ph = p - L.h;
    float2 sg = select(float2(-1.0), float2(1.0), ph >= 0.0);          // not sign(): sign(0) == 0
    float2 w = abs(ph) - (L.half_box - L.round);
    float g = max(w.x, w.y);
    float3 f;
    if (g > 0.0) { float2 wp = max(w, 0.0); float lw = length(wp); f = float3(lw - L.round, sg * wp / lw); }
    else { f = float3(g - L.round, w.x > w.y ? float2(sg.x, 0.0) : float2(0.0, sg.y)); }
    if (L.inv_len2 > 0.0 && L.radius > 0.0) {
        float2 e = L.h - L.b;
        float u = clamp(dot(p - L.b, e) * L.inv_len2, 0.0, 1.0);
        float2 v = p - (L.b + e * u); float l = length(v);
        float q = 1.0 - 4.0 * L.neck * u * (1.0 - u);
        float sl = L.lip * (2.0 * u - 1.0);
        f = liquid_smin(f, float3((l - L.radius * q) * rsqrt(1.0 + sl * sl), liquid_dir(v, l)), L.k);
    }
    for (uint i = 0u; i < 3u; i++) {
        float4 bd = L.bead[i];
        if (bd.z > 0.0) { float2 v = p - bd.xy; float l = length(v);
                          f = liquid_smin(f, float3(l - bd.z, liquid_dir(v, l)), L.k); }
    }
    return f;
}

static inline bool liquid_out(float2 p, constant LiquidU& L) {   // hole, or beyond reach (== the bands' reach)
    if (p.x >= L.hole.x && p.x < L.hole.z && p.y >= L.hole.y && p.y < L.hole.w) return true;
    float2 e = L.h - L.b;
    float u0 = clamp(dot(p - L.b, e) * L.inv_len2, 0.0, 1.0);
    float ds = L.inv_len2 > 0.0 ? length(p - (L.b + e * u0)) : INFINITY;
    float2 o = max(max(L.hole.xy - p, p - L.hole.zw), 0.0);
    return min(ds, length(o)) > L.reach;
}

// the bevel at field value f: t, nz, nr, the unit normal
static inline float liquid_alpha_at(float3 f, constant LiquidU& L) {
    float cov = clamp(0.5 - f.x, 0.0, 1.0);
    if (cov <= 0.0) return 0.0;
    float t = clamp(-f.x * L.inv_bezel, 0.0, 1.0);
    float s = 1.0 - t; float s2 = s * s; float s3 = s2 * s;
    float z = sqrt(sqrt(max(1.0 - s2 * s2, 0.0))); float z3 = z * z * z;
    float nz = z3 * rsqrt(max(s3 * s3 + z3 * z3, 1e-12));
    float fr = 1.0 - nz;
    float rim = 0.04 + 0.96 * fr * fr;
    float gl = dot(f.yz, f.yz);
    float2 n = gl > 1e-12 ? f.yz * rsqrt(gl) : float2(0.0);
    float bt = clamp((t - 0.04) * 2.5, 0.0, 1.0);
    float band = 4.0 * bt * (1.0 - bt);
    float nl = dot(n, L.light);
    float sp = max(nl, 0.0);  sp = sp * sp * sp * band;
    float bk = max(-nl, 0.0); bk = bk * bk * bk * band;
    return L.envelope * cov * saturate(L.body + L.rim * rim + L.spec * sp + L.back * bk);
}

fragment float4 liquid_fragment(GOut in [[stage_in]], constant LiquidU& L [[buffer(0)]]) {
    float2 p = in.pos.xy - L.origin;
    if (liquid_out(p, L)) return float4(0.0);
    float a = in.color.a * liquid_alpha_at(liquid_field(p, L), L);
    return float4(in.color.rgb * a, a);                 // premultiplied cursor colour, OVER
}

// ---- (b), later: blending OFF (Blend::Replace), after a blit of the trail's bounds into `under`.
struct LensU { float2 under_at; float lens; float lens_norm; };
static inline float4 lens_read(texture2d<float, access::read> t, int2 q) {
    return t.read(uint2(clamp(q, int2(0), int2(t.get_width(), t.get_height()) - 1)));
}
static inline float4 lens_bilinear(texture2d<float, access::read> t, float2 q) {  // by hand: portable
    float2 f0 = floor(q - 0.5); float2 w = (q - 0.5) - f0; int2 i = int2(f0);
    return mix(mix(lens_read(t, i), lens_read(t, i + int2(1, 0)), w.x),
               mix(lens_read(t, i + int2(0, 1)), lens_read(t, i + int2(1, 1)), w.x), w.y);
}
fragment float4 liquid_lens_fragment(GOut in [[stage_in]], constant LiquidU& L [[buffer(0)]],
                                     constant LensU& K [[buffer(1)]],
                                     texture2d<float, access::read> under [[texture(0)]]) {
    float2 q = in.pos.xy - K.under_at;
    float4 dst = lens_read(under, int2(floor(q)));
    float2 p = in.pos.xy - L.origin;
    if (liquid_out(p, L)) return dst;                    // identity: exact byte round trip
    float3 f = liquid_field(p, L);
    float cov = clamp(0.5 - f.x, 0.0, 1.0);
    if (cov <= 0.0) return dst;
    float t = clamp(-f.x * L.inv_bezel, 0.0, 1.0);
    float s = 1.0 - t; float s2 = s * s; float s3 = s2 * s;
    float z = sqrt(sqrt(max(1.0 - s2 * s2, 0.0))); float z3 = z * z * z;
    float inv = rsqrt(max(s3 * s3 + z3 * z3, 1e-12));
    float nz = z3 * inv; float nr = s3 * inv;
    float gl = dot(f.yz, f.yz);
    float2 n = gl > 1e-12 ? f.yz * rsqrt(gl) : float2(0.0);
    const float eta = 1.0 / 1.5;                         // Snell through the squircle bevel (webglass)
    float lat = (eta * nz - sqrt(max(1.0 - eta * eta * (1.0 - nz * nz), 0.0))) * nr * z * K.lens_norm; // <= 0
    float4 bent = lens_bilinear(under, q + n * (lat * K.lens * L.envelope));   // inward: magnifies
    float4 base = mix(dst, bent, cov);
    float a = in.color.a * liquid_alpha_at(f, L);
    float4 glass = float4(in.color.rgb * a, a);
    return glass + base * (1.0 - glass.a);
}
